import assert from 'node:assert/strict';
import fs from 'node:fs';
import {spawnSync} from 'node:child_process';
import {createHash} from 'node:crypto';
const root='F:/VisibleMedicine/staging/20261023-studio-session-drafts',site=root+'/website';
const phase=process.argv[2];assert(['before','current','original','original-admitted','before-final','current-final','original-final'].includes(phase));
