const component=phase.startsWith('before')?root+'/StudioForms.before.raw':site+'/components/StudioForms.tsx';
const args=['--max-old-space-size=128','--test','--test-concurrency=1','--test-reporter=tap',...tests];
const start={at:new Date().toISOString(),cwd:site,args,component,componentSha256:sha(fs.readFileSync(component)),tests:tests.map(path=>({path,sha256:sha(fs.readFileSync(site+'/'+path))}))};
fs.writeFileSync(file+'.started.json',JSON.stringify(start,null,2)+'\n',{flag:'wx'});
const result=spawnSync(process.execPath,args,{cwd:site,encoding:'utf8',windowsHide:true,maxBuffer:10*1024*1024,env:{...process.env,NODE_OPTIONS:'--max-old-space-size=128',STUDIO_SESSION_FORMS_SOURCE:component}});
