const counts=Object.fromEntries([...(result.stdout??'').matchAll(/^# (tests|pass|fail|cancelled|skipped|todo) (\d+)\s*$/gm)].map(m=>[m[1],Number(m[2])]));
const end={...start,finishedAt:new Date().toISOString(),exitCode:result.status,signal:result.signal,error:result.error?.message??null,counts,stdoutSha256:sha(result.stdout??''),stderrSha256:sha(result.stderr??'')};
fs.writeFileSync(file+'.json',JSON.stringify(end,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({phase,exitCode:result.status,counts}));
assert.equal(result.status,phase.startsWith('before')?1:0);assert.equal(counts.skipped,0);assert.equal(counts.cancelled,0);if(phase.startsWith('before'))assert(counts.fail>0);else assert.equal(counts.fail,0);
